#include "change_feed.hpp"
#include <chrono>
#include <filesystem>
#include <iostream>
using namespace edudb;
namespace fs=std::filesystem;
namespace {
int checks=0;
void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
json definition(){return {{"columns",json::array({json{{"name","id"},{"type","INTEGER"},{"length",0},{"not_null",false}},json{{"name","value"},{"type","VARCHAR"},{"length",7800},{"not_null",false}}})},{"rows",json::array()},{"indexes",json::array()}};}
void class_cases(){TransactionChangeFeed f(1024);f.emit("a","INSERT",1,nullptr,json::array({1}));check(f.read("",0)["events"].empty(),"unsubscribed work emits no events");f.enable({"a"});f.emit("a","INSERT",1,nullptr,json::array({1}));auto point=f.snapshot();f.emit("a","UPDATE",1,json::array({1}),json::array({2}));auto prior=f.read("",0)["last_seq"].get<std::uint64_t>();f.restore(point);f.emit("a","UPDATE",1,json::array({1}),json::array({3}));auto next=f.read("a",prior);check(next["events"].size()==1&&next["events"][0]["seq"].get<std::uint64_t>()>prior,"savepoint never rewinds global event sequence");check(next["events"][0]["old_row"]==json::array({1})&&next["events"][0]["new_row"]==json::array({3}),"rolled-back mutation not retained");bool limit=false;try{f.emit("a","INSERT",2,nullptr,json::array({std::string(2000,'x')}));}catch(const DbError& e){limit=e.code=="CHANGEFEED_LIMIT";}check(limit,"bounded encoded-event resource failure");check(f.read("",0)["events"].size()==2,"failed append does not publish partial event");}
void storage_cases(const fs::path& path){Storage db(path.u8string(),3);auto tx=db.begin();db.write_table(tx,"a",definition());db.write_table(tx,"b",definition());db.commit(tx);tx=db.begin();db.enable_changefeed(tx,{"a"});auto rid=db.insert_row(tx,"a",json::array({1,"initial"}));db.insert_row(tx,"b",json::array({2,"not subscribed"}));auto first=db.read_changefeed(tx);check(first["events"].size()==1&&first["events"][0]["kind"]=="INSERT","native insert filtered by real subscription");db.update_row(tx,"a",rid,json::array({1,"initial"}));check(db.read_changefeed(tx)["events"].size()==1,"actual no-op emits zero events");db.savepoint(tx,"keep");db.update_row(tx,"a",rid,json::array({1,"rolled back"}));db.insert_row(tx,"a",json::array({3,"also rolled back"}));auto high=db.read_changefeed(tx)["last_seq"].get<std::uint64_t>();db.rollback_to(tx,"keep");check(db.read_changefeed(tx)["last_seq"]==high&&db.read_changefeed(tx)["events"].size()==1,"native rollback restores events but retains sequence watermark");db.update_row(tx,"a",rid,json::array({1,"final"}));auto after=db.read_changefeed(tx,"a",high);check(after["events"].size()==1&&after["events"][0]["old_row"][1]=="initial"&&after["events"][0]["new_row"][1]=="final","post-rollback native mutation cannot be skipped by a cursor");auto t=db.read_table(tx,"a");t["record_format"]="VARIABLE";db.write_table(tx,"a",t);check(db.read_changefeed(tx)["events"].back()["kind"]=="RESET","rewrite is one explicit reset rather than invented row deltas");auto all=db.read_changefeed(tx)["events"].size();check(all==3,"internal rewrite insertions do not duplicate events");db.drop_table(tx,"a");check(db.read_changefeed(tx)["events"].back()["kind"]=="RESET","drop reset captured");db.rollback(tx);tx=db.begin();check(db.read_table(tx,"a")["rows"].empty()&&db.read_table(tx,"b")["rows"].empty(),"feed and every subscribed or unsubscribed write rollback atomically");db.commit(tx);}
void overflow(const fs::path& path){Storage db(path.u8string(),3);auto tx=db.begin();db.write_table(tx,"t",definition());auto rid=db.insert_row(tx,"t",json::array({1,std::string(7000,'m')}));db.commit(tx);tx=db.begin();db.enable_changefeed(tx,{"t"});bool failed=false;for(int i=0;i<5000;++i)try{db.update_row(tx,"t",rid,json::array({1,std::string(7000,static_cast<char>('a'+i%20))}));}catch(const DbError& e){failed=e.code=="CHANGEFEED_LIMIT";break;}check(failed,"real repeated same-page writes hit bounded feed budget");bool blocked=false;try{db.commit(tx);}catch(const DbError& e){blocked=e.code=="TRANSACTION_ABORTED";}check(blocked&&!db.recovery_required(),"resource failure prevents commit without poisoning committed storage");tx=db.begin();check(db.read_table(tx,"t")["rows"][0][1]==std::string(7000,'m'),"changefeed overflow does not publish partial base-table writes");db.commit(tx);}
void metadata_cases(const fs::path& path){
    Storage db(path.u8string(),3);auto tx=db.begin();auto t=definition();t["materialized_view"]={{"definition","SELECT id,value FROM source"}};
    db.write_table(tx,"v",t);db.insert_row(tx,"v",json::array({1,"kept"}));db.commit(tx);
    tx=db.begin();auto before=db.read_table(tx,"v");db.savepoint(tx,"s");db.set_materialized_metadata(tx,"v",json{{"cursor",12}});db.rollback_to(tx,"s");
    check(!db.read_table(tx,"v",false).contains("materialized_refresh_state"),"savepoint restores metadata state");
    db.set_materialized_metadata(tx,"v",json{{"cursor",19}});db.set_materialized_metadata(tx,"v",json{{"cursor",20}});db.commit(tx);
    auto metrics=db.transaction_stats(tx);check(metrics["private_pages"]==1&&metrics["private_heap_pages"]==0&&metrics["private_index_pages"]==0&&metrics["wal_bytes"]==8352,"metadata-only update has one final descriptor WAL image and no user or index pages");
    tx=db.begin();auto after=db.read_table(tx,"v");for(auto key:{"data_version","schema_version","physical_version","rows","row_ids"})check(before.at(key)==after.at(key),"refresh state does not change row identity or structural versions");
    check(after["materialized_refresh_state"]["cursor"]==20,"final metadata state persists");db.commit(tx);
    TransactionOptions ro;ro.read_only=true;tx=db.begin(ro);bool rejected=false;try{db.set_materialized_metadata(tx,"v",json{{"cursor",99}});}catch(const DbError& e){rejected=e.code=="READ_ONLY_TRANSACTION";}check(rejected,"read-only metadata update rejected");db.rollback(tx);
}
}
int main(){try{auto root=fs::absolute(fs::path("changefeed-test-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())));check(!fs::exists(root),"new test root");fs::create_directory(root);class_cases();storage_cases(root/"native");metadata_cases(root/"metadata");overflow(root/"budget");std::cout<<"PASS transaction changefeed "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
